schemas.schema-03-posts.prisma:
/// Main discussion posts created by members or moderators.
///
/// Represents the primary content entities that form discussion threads on
/// the economic/political discussion board. Each post contains a title,
/// content body, and optional attachments. Posts are organized by channels
/// and sections to categorize discussions by topic.
///
/// Posts support various statuses including draft, published, and archived
/// states to manage content lifecycle. Authors can edit their posts within a
/// limited timeframe, and the system maintains edit history for moderation
/// purposes.
///
/// The table implements polymorphic ownership to support both member-created
/// and moderator-created posts, with proper foreign key relationships to the
/// respective author tables.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Channel categorization for the post. {@link discussion_board_channels.id}
  discussion_board_channel_id String @db.Uuid

  /// Section categorization within the channel. {@link
  /// discussion_board_sections.id}
  discussion_board_section_id String @db.Uuid

  /// Type of actor who created the post (member or moderator). Used for quick
  /// filtering and relationship resolution.
  actor_type String

  /// Post title summarizing the discussion topic. Must be between 5 and 200
  /// characters.
  title String

  /// Main content body of the post supporting Markdown formatting. Must be
  /// between 50 and 10,000 characters.
  content String

  /// Current status of the post: draft, published, archived, or deleted.
  status String

  /// Whether the post is pinned to the top of the discussion board.
  is_pinned Boolean

  /// Whether the post is locked from further comments.
  is_locked Boolean

  /// Timestamp when the post was originally created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the post was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the post was published and made visible to users.
  published_at DateTime? @db.Timestamptz

  /// Timestamp when the post was archived due to age or inactivity.
  archived_at DateTime? @db.Timestamptz

  /// Timestamp when the post was soft-deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel discussion_board_channels @relation(fields: [discussion_board_channel_id], references: [id], onDelete: Cascade)
  section discussion_board_sections @relation(fields: [discussion_board_section_id], references: [id], onDelete: Cascade)

  discussion_board_comments discussion_board_comments[]
  discussion_board_post_attachments discussion_board_post_attachments[]
  discussion_board_content_reports_of_members discussion_board_content_reports_of_members[]
  discussion_board_content_reports_of_moderators discussion_board_content_reports_of_moderators[]
  discussion_board_post_views discussion_board_post_views[]
  discussion_board_post_likes discussion_board_post_likes[]
  discussion_board_user_bookmarks discussion_board_user_bookmarks[]

  @@unique([title, discussion_board_channel_id])
  @@index([actor_type, created_at])
  // spellchecker: ignore-next-line
  @@index([discussion_board_channel_id, created_at], map: "discussion_board_posts_discussion_board_channel_id_cre_c4184281")
  // spellchecker: ignore-next-line
  @@index([discussion_board_section_id, created_at], map: "discussion_board_posts_discussion_board_section_id_cre_6239ad36")
  @@index([status, created_at])
  @@index([is_pinned, created_at])
  @@index([status, is_pinned, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-04-comments.prisma:
/// Threaded comments on discussion board posts with support for attachments
/// and moderation.
///
/// Stores user comments on discussion posts with hierarchical threading
/// capabilities. Each comment belongs to a specific post and can have parent
/// comments for threaded discussions. Comments support attachment uploads
/// and have their own lifecycle independent from posts.
///
/// Comments require member authentication and can be moderated separately
/// from posts. The system maintains comment threading up to 3 levels deep as
/// specified in requirements. Comments have their own validation rules and
/// management workflows distinct from post content.
///
/// Comment lifecycle includes creation, editing within time limits, and soft
/// deletion. The system tracks comment status and maintains audit trails for
/// moderation purposes.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the parent post. {@link discussion_board_posts.id}
  discussion_board_post_id String @db.Uuid

  /// Reference to the comment author. {@link discussion_board_members.id}
  discussion_board_member_id String @db.Uuid

  /// Reference to parent comment for threaded replies. {@link
  /// discussion_board_comments.id}
  parent_id String? @db.Uuid

  /// Comment text content with Markdown formatting support. Validated for
  /// length between 1 and 2000 characters as per requirements.
  content String

  /// Current comment status: 'draft', 'published', 'deleted'. Controls comment
  /// visibility and management.
  status String

  /// Nesting level of comment in thread hierarchy. Root comments have level 0,
  /// replies increment by 1. Limited to maximum 3 levels deep.
  thread_level Int @db.Integer

  /// Timestamp when comment was initially created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when comment was last modified.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when comment was soft deleted. Null if comment is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  post discussion_board_posts @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  author discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)
  parent discussion_board_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive discussion_board_comments[] @relation("recursive")
  discussion_board_comment_attachments discussion_board_comment_attachments[]
  discussion_board_content_reports_of_members discussion_board_content_reports_of_members[]
  discussion_board_content_reports_of_moderators discussion_board_content_reports_of_moderators[]
  discussion_board_comment_likes discussion_board_comment_likes[]

  // spellchecker: ignore-next-line
  @@index([discussion_board_post_id, created_at], map: "discussion_board_comments_discussion_board_post_id_cre_571d2d84")
  // spellchecker: ignore-next-line
  @@index([discussion_board_member_id, created_at], map: "discussion_board_comments_discussion_board_member_id_c_c3eff834")
  @@index([parent_id, created_at])
  @@index([status, created_at])
  @@index([thread_level])
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-05-attachments.prisma:
/// File attachments associated with discussion board posts.
///
/// Stores metadata for files uploaded by members to support their posts with
/// additional evidence, research materials, or visual content. Each
/// attachment is specifically linked to a single post and maintains its own
/// lifecycle separate from the post content.
///
/// Attachments undergo security scanning and validation before being made
/// available for download. The system tracks upload status, file properties,
/// and access patterns to ensure proper attachment management.
///
/// Supports various file types including images (JPG, PNG, GIF) and
/// documents (PDF, DOC, DOCX) with size limitations enforced during upload.
///
/// @namespace Attachments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the parent post that this attachment belongs to. {@link
  /// discussion_board_posts.id}
  discussion_board_post_id String @db.Uuid

  /// Reference to the member who uploaded this attachment. {@link
  /// discussion_board_members.id}
  discussion_board_member_id String @db.Uuid

  /// Reference to the session context when the attachment was uploaded. {@link
  /// discussion_board_member_sessions.id}
  discussion_board_member_session_id String @db.Uuid

  /// Original name of the uploaded file as provided by the user.
  file_name String

  /// MIME type or file extension indicating the file format (e.g., image/jpeg,
  /// application/pdf).
  file_type String

  /// Size of the file in bytes. Used for validation and display purposes.
  file_size Int @db.Integer

  /// Path or identifier for the file in the storage system.
  storage_path String

  /// Current status of the attachment upload process (pending, processing,
  /// completed, failed).
  upload_status String

  /// Result of security/virus scanning (clean, suspicious, infected, pending).
  security_scan_result String?

  /// Optional description provided by the user for the attachment.
  description String?

  /// Number of times this attachment has been downloaded by users.
  download_count Int @db.Integer

  /// Timestamp when the attachment record was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the attachment record was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the attachment was soft deleted. Null if still active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  post discussion_board_posts @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  member discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade, map: "discussion_board_post_attachments_discussion_board_mem_5bce12e2")
  // spellchecker: ignore-next-line
  memberSession discussion_board_member_sessions @relation(fields: [discussion_board_member_session_id], references: [id], onDelete: Cascade, map: "discussion_board_post_attachments_discussion_board_mem_22acd303")

  // spellchecker: ignore-next-line
  @@index([discussion_board_member_session_id], map: "discussion_board_post_attachments_discussion_board_mem_3db2bb2e")

  // spellchecker: ignore-next-line
  @@index([discussion_board_post_id, created_at], map: "discussion_board_post_attachments_discussion_board_pos_2886a87c")
  // spellchecker: ignore-next-line
  @@index([discussion_board_member_id, created_at], map: "discussion_board_post_attachments_discussion_board_mem_e84d5b58")
