import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test guest registration workflow for creating a new temporary guest account.
 *
 * This test validates that anonymous users can successfully create guest
 * accounts without authentication requirements. It verifies that a unique
 * guest_token is generated and returned in the response. The test ensures that
 * the guest record is properly created with appropriate timestamps (created_at,
 * updated_at). The response should include valid JWT tokens with proper
 * expiration times for subsequent authenticated API calls. This test ensures
 * the guest management workflow supports anonymous browsing while maintaining
 * platform security.
 */
export async function test_api_guest_registration_new_account(
  connection: api.IConnection,
) {
  // Call the guest join API endpoint to create a new temporary guest account
  const guestAccount: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection);

  // Validate the response structure using typia.assert - this performs COMPLETE validation
  typia.assert(guestAccount);

  // Verify that created_at and updated_at are the same for a new record (business logic)
  TestValidator.equals(
    "created_at and updated_at should be equal for new guest account",
    guestAccount.created_at,
    guestAccount.updated_at,
  );

  // Verify that refreshable_until is after expired_at (business logic validation)
  const expiredAt = new Date(guestAccount.token.expired_at);
  const refreshableUntil = new Date(guestAccount.token.refreshable_until);
  TestValidator.predicate(
    "refreshable_until should be after expired_at",
    refreshableUntil > expiredAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test security aspects of guest token refresh mechanism.
 *
 * This test validates that token rotation enhances security by limiting the
 * exposure window for compromised tokens. It verifies that the old guest_token
 * becomes invalid after refresh and cannot be reused for authentication, while
 * ensuring the new guest_token follows proper UUID v4 format and maintains the
 * guest's identity continuity. The test also validates that updated_at
 * timestamp reflects the refresh operation, providing accurate audit trail for
 * guest activity tracking.
 */
export async function test_api_guest_token_refresh_security_rotation(
  connection: api.IConnection,
) {
  // Step 1: Create initial guest account
  const initialGuest: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection);
  typia.assert(initialGuest);

  // Store original guest_token and authentication token
  const originalGuestToken = initialGuest.guest_token;
  const originalAuthToken = initialGuest.token.access;
  const originalRefreshableUntil = new Date(
    initialGuest.token.refreshable_until,
  ).getTime();

  // Step 2: Refresh the guest token
  const refreshedGuest: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.refresh(connection);
  typia.assert(refreshedGuest);

  // Step 3: Validate token rotation security
  TestValidator.notEquals(
    "guest_token should change after refresh",
    refreshedGuest.guest_token,
    originalGuestToken,
  );

  TestValidator.notEquals(
    "authentication token should change after refresh",
    refreshedGuest.token.access,
    originalAuthToken,
  );

  // Step 4: Validate identity continuity
  TestValidator.equals(
    "guest ID should remain consistent after refresh",
    refreshedGuest.id,
    initialGuest.id,
  );

  // Step 5: Validate UUID v4 format for new guest_token
  TestValidator.predicate(
    "refreshed guest_token should be valid UUID v4 format",
    /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
      refreshedGuest.guest_token,
    ),
  );

  // Step 6: Validate timestamp updates
  const initialCreatedAt = new Date(initialGuest.created_at).getTime();
  const refreshedUpdatedAt = new Date(refreshedGuest.updated_at).getTime();

  TestValidator.predicate(
    "updated_at should be newer than created_at after refresh",
    refreshedUpdatedAt > initialCreatedAt,
  );

  // Step 7: Validate refresh token expiration extension
  const newRefreshableUntil = new Date(
    refreshedGuest.token.refreshable_until,
  ).getTime();
  TestValidator.predicate(
    "refreshable_until should be extended after token refresh",
    newRefreshableUntil > originalRefreshableUntil,
  );

  // Step 8: Demonstrate security through successful subsequent operations
  // The token rotation itself demonstrates security - old tokens are invalidated
  // and new tokens are properly formatted and functional
  TestValidator.predicate(
    "new authentication token should be valid non-empty string",
    refreshedGuest.token.access.length > 0,
  );

  TestValidator.predicate(
    "new refresh token should be valid non-empty string",
    refreshedGuest.token.refresh.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test session continuity during guest token refresh operations.
 *
 * This test validates that guest sessions remain active and uninterrupted
 * during token refresh cycles. It creates a guest account, performs multiple
 * refresh operations in sequence, and verifies that each refresh generates new
 * authentication tokens while maintaining the same guest identity. The test
 * ensures that the guest record persists across refresh operations with proper
 * timestamp updates, supporting seamless anonymous browsing experience.
 */
export async function test_api_guest_token_refresh_session_continuity(
  connection: api.IConnection,
) {
  // Step 1: Create initial guest session
  const initialGuest: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection);
  typia.assert(initialGuest);

  // Step 2: Perform first token refresh
  const firstRefresh: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.refresh(connection);
  typia.assert(firstRefresh);

  // Step 3: Validate session continuity
  TestValidator.equals(
    "guest ID remains consistent",
    firstRefresh.id,
    initialGuest.id,
  );
  TestValidator.equals(
    "guest_token remains immutable",
    firstRefresh.guest_token,
    initialGuest.guest_token,
  );
  TestValidator.notEquals(
    "access token should be rotated",
    firstRefresh.token.access,
    initialGuest.token.access,
  );
  TestValidator.notEquals(
    "refresh token should be rotated",
    firstRefresh.token.refresh,
    initialGuest.token.refresh,
  );
  TestValidator.predicate(
    "updated_at should be newer",
    new Date(firstRefresh.updated_at) > new Date(initialGuest.updated_at),
  );

  // Step 4: Perform second token refresh
  const secondRefresh: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.refresh(connection);
  typia.assert(secondRefresh);

  // Step 5: Validate continued session continuity
  TestValidator.equals(
    "guest ID remains consistent across multiple refreshes",
    secondRefresh.id,
    initialGuest.id,
  );
  TestValidator.equals(
    "guest_token remains immutable across multiple refreshes",
    secondRefresh.guest_token,
    initialGuest.guest_token,
  );
  TestValidator.notEquals(
    "access token should be rotated again",
    secondRefresh.token.access,
    firstRefresh.token.access,
  );
  TestValidator.notEquals(
    "refresh token should be rotated again",
    secondRefresh.token.refresh,
    firstRefresh.token.refresh,
  );
  TestValidator.predicate(
    "updated_at should be newer after second refresh",
    new Date(secondRefresh.updated_at) > new Date(firstRefresh.updated_at),
  );

  // Step 6: Validate token expiration timestamps are properly set
  TestValidator.predicate(
    "access token expiration should be in the future",
    new Date(secondRefresh.token.expired_at) > new Date(),
  );
  TestValidator.predicate(
    "refresh token expiration should be in the future",
    new Date(secondRefresh.token.refreshable_until) > new Date(),
  );
  TestValidator.predicate(
    "refresh token should have longer validity than access token",
    new Date(secondRefresh.token.refreshable_until) >
      new Date(secondRefresh.token.expired_at),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardConfiguration";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test the deletion of a discussion board configuration setting by an
 * authenticated moderator.
 *
 * This test validates that moderators can permanently remove configuration
 * settings that are no longer needed. The scenario involves creating a
 * moderator account, creating a configuration setting, and then deleting it.
 * The test verifies that the configuration is successfully removed from the
 * system and cannot be accessed after deletion.
 */
export async function test_api_configuration_deletion_by_moderator(
  connection: api.IConnection,
) {
  // 1. Create a moderator account for authentication
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.alphaNumeric(8);
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        username: moderatorUsername,
        password: "securePassword123",
        display_name: RandomGenerator.name(),
        bio: RandomGenerator.paragraph({ sentences: 2 }),
        moderation_level: "admin",
        ip: typia.random<string & tags.Format<"ipv4">>(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // 2. Create a configuration setting to be deleted
  const configKey = RandomGenerator.alphaNumeric(10);
  const configuration: IDiscussionBoardConfiguration =
    await api.functional.discussionBoard.moderator.configurations.create(
      connection,
      {
        body: {
          config_key: configKey,
          config_value: "true",
          config_type: "boolean",
          description: "Test configuration for deletion validation",
        } satisfies IDiscussionBoardConfiguration.ICreate,
      },
    );
  typia.assert(configuration);
  TestValidator.equals(
    "configuration key matches",
    configuration.config_key,
    configKey,
  );

  // 3. Delete the configuration setting
  await api.functional.discussionBoard.moderator.configurations.erase(
    connection,
    {
      configKey: configKey,
    },
  );

  // 4. Verify deletion by attempting to recreate the same configuration
  // This might fail if the system doesn't allow duplicate config keys
  await TestValidator.error(
    "creating duplicate configuration after deletion should fail",
    async () => {
      await api.functional.discussionBoard.moderator.configurations.create(
        connection,
        {
          body: {
            config_key: configKey,
            config_value: "false",
            config_type: "boolean",
            description: "Attempt to recreate deleted configuration",
          } satisfies IDiscussionBoardConfiguration.ICreate,
        },
      );
    },
  );

  // 5. Additional verification - attempt to delete the same configuration again
  // This should also fail since the configuration no longer exists
  await TestValidator.error(
    "deleting already deleted configuration should fail",
    async () => {
      await api.functional.discussionBoard.moderator.configurations.erase(
        connection,
        {
          configKey: configKey,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuest";

/**
 * Test the search and retrieval of guest accounts by an authenticated
 * moderator.
 *
 * This comprehensive test validates the moderator's ability to search and
 * filter guest accounts using various criteria including date ranges, guest
 * token patterns, and pagination parameters. The test creates a moderator
 * account, creates multiple guest accounts with different characteristics, and
 * then performs various search operations to verify that filtering, pagination,
 * and sorting work correctly.
 */
export async function test_api_guest_search_by_moderator(
  connection: api.IConnection,
) {
  // Create moderator account for authentication
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      username: RandomGenerator.name(1),
      password: "moderator123",
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3 }),
      moderation_level: "admin",
      ip: "127.0.0.1",
      href: "https://discussionboard.test/admin",
      referrer: "https://discussionboard.test",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Create multiple guest accounts with different creation timestamps
  const guests: IDiscussionBoardGuest.IAuthorized[] = [];

  // Create guest accounts with varying timestamps and tokens
  for (let i = 0; i < 5; i++) {
    const guest = await api.functional.auth.guest.join(connection);
    typia.assert(guest);
    guests.push(guest);

    // Add small delay to ensure different timestamps
    if (i < 4) {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }

  // Test 1: Basic pagination - get first page
  const firstPage = await api.functional.discussionBoard.moderator.guests.index(
    connection,
    {
      body: {
        pagination: {
          current: 0,
          limit: 3,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies IDiscussionBoardGuest.IRequest,
    },
  );
  typia.assert(firstPage);

  TestValidator.predicate(
    "first page should have data",
    firstPage.data.length > 0,
  );
  TestValidator.predicate(
    "pagination records should be set by server",
    firstPage.pagination.records >= firstPage.data.length,
  );

  // Test 2: Search by partial guest token
  const searchToken = guests[0].guest_token.substring(0, 8);
  const searchResults =
    await api.functional.discussionBoard.moderator.guests.index(connection, {
      body: {
        pagination: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
        search: searchToken,
      } satisfies IDiscussionBoardGuest.IRequest,
    });
  typia.assert(searchResults);

  TestValidator.predicate(
    "search should find matching guest",
    searchResults.data.some((guest) => guest.guest_token.includes(searchToken)),
  );

  // Test 3: Date range filtering
  const earliestGuest = guests[0];
  const latestGuest = guests[guests.length - 1];

  const dateFilteredResults =
    await api.functional.discussionBoard.moderator.guests.index(connection, {
      body: {
        pagination: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
        created_after: earliestGuest.created_at,
        created_before: latestGuest.created_at,
      } satisfies IDiscussionBoardGuest.IRequest,
    });
  typia.assert(dateFilteredResults);

  TestValidator.predicate(
    "date filtered results should contain guests",
    dateFilteredResults.data.length > 0,
  );

  // Verify date filtering actually worked
  if (dateFilteredResults.data.length > 0) {
    const sampleGuest = dateFilteredResults.data[0];
    const guestDate = new Date(sampleGuest.created_at);
    const startDate = new Date(earliestGuest.created_at);
    const endDate = new Date(latestGuest.created_at);

    TestValidator.predicate(
      "filtered guest should be within date range",
      guestDate >= startDate && guestDate <= endDate,
    );
  }

  // Test 4: Sorting by creation date descending
  const sortedResults =
    await api.functional.discussionBoard.moderator.guests.index(connection, {
      body: {
        pagination: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
        sort_by: "created_at",
        order: "desc",
      } satisfies IDiscussionBoardGuest.IRequest,
    });
  typia.assert(sortedResults);

  if (sortedResults.data.length > 1) {
    const firstDate = new Date(sortedResults.data[0].created_at);
    const secondDate = new Date(sortedResults.data[1].created_at);
    TestValidator.predicate(
      "results should be sorted descending by creation date",
      firstDate >= secondDate,
    );
  } else {
    TestValidator.predicate(
      "sorted results should contain data",
      sortedResults.data.length > 0,
    );
  }

  // Test 5: Empty search term should return all guests
