  typia.assert(recentChannels);

  // Test 9: Pagination boundary test
  if (firstPage.pagination.pages > 0) {
    const lastPage = await api.functional.discussionBoard.channels.index(
      connection,
      {
        body: {
          page: firstPage.pagination.pages,
