import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test moderator deletion when the target moderator has active authentication
 * sessions. This scenario validates that the system properly handles moderator
 * deletion when sessions are present, ensuring that active sessions are
 * terminated and the moderator account is completely removed from the system.
 * The test covers session cleanup and verification that no orphaned sessions
 * remain after deletion.
 */
export async function test_api_moderator_deletion_with_active_sessions(
  connection: api.IConnection,
) {
  // 1. Create admin moderator account for authorization
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin123";
  const admin: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: adminEmail,
        username: RandomGenerator.alphaNumeric(8),
        password: adminPassword,
        display_name: RandomGenerator.name(),
        bio: RandomGenerator.paragraph({ sentences: 5 }),
        moderation_level: "admin",
        href: "https://example.com/join",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(admin);

  // 2. Create target moderator account with authentication sessions
  const targetEmail = typia.random<string & tags.Format<"email">>();
  const targetPassword = "target123";
  const targetUsername = RandomGenerator.alphaNumeric(8);
  const target: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: targetEmail,
        username: targetUsername,
        password: targetPassword,
        display_name: RandomGenerator.name(),
        bio: RandomGenerator.paragraph({ sentences: 3 }),
        moderation_level: "basic",
        href: "https://example.com/join",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(target);
  TestValidator.equals(
    "target moderator created",
    target.username,
    targetUsername,
  );

  // 3. Create channel as prerequisite
  const channel: IDiscussionBoardChannel =
    await api.functional.discussionBoard.moderator.channels.create(connection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
      } satisfies IDiscussionBoardChannel.ICreate,
    });
  typia.assert(channel);

  // 4. Create active authentication session for target moderator
  // Switch to target moderator
  const targetSession: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.login(connection, {
      body: {
        email_or_username: targetEmail,
        password: targetPassword,
        href: "https://example.com/login",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardModerator.ILogin,
    });
  typia.assert(targetSession);
  TestValidator.equals("target session active", targetSession.id, target.id);

  // Verify target moderator can access functionality
  const targetChannel: IDiscussionBoardChannel =
    await api.functional.discussionBoard.moderator.channels.create(connection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
      } satisfies IDiscussionBoardChannel.ICreate,
    });
  typia.assert(targetChannel);

  // 5. Switch back to admin moderator and delete target account
  await api.functional.auth.moderator.login(connection, {
    body: {
      email_or_username: adminEmail,
      password: adminPassword,
      href: "https://example.com/login",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Delete the target moderator
  const deletedModerator: IDiscussionBoardModerator =
    await api.functional.discussionBoard.moderator.moderators.erase(
      connection,
      {
        username: targetUsername,
      },
    );
  typia.assert(deletedModerator);
  TestValidator.equals(
    "deleted moderator username matches",
    deletedModerator.username,
    targetUsername,
  );

  // 6. Verify deletion by attempting to use the target moderator's session
  // Create a new connection without authentication headers
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  // Attempt to login with deleted moderator credentials
  await TestValidator.error("deleted moderator cannot login", async () => {
    await api.functional.auth.moderator.login(unauthConn, {
      body: {
        email_or_username: targetEmail,
        password: targetPassword,
        href: "https://example.com/login",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardModerator.ILogin,
    });
  });

  // Attempt to access moderator functionality with deleted credentials
  await TestValidator.error(
    "deleted moderator cannot access channels",
    async () => {
      await api.functional.discussionBoard.moderator.channels.create(
        unauthConn,
        {
          body: {
            name: RandomGenerator.paragraph({ sentences: 2 }),
            description: RandomGenerator.content({ paragraphs: 1 }),
            status: "active",
          } satisfies IDiscussionBoardChannel.ICreate,
        },
      );
    },
  );

  // Verify admin can still access functionality
  const adminChannel: IDiscussionBoardChannel =
    await api.functional.discussionBoard.moderator.channels.create(connection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
      } satisfies IDiscussionBoardChannel.ICreate,
    });
  typia.assert(adminChannel);

  // Final verification: Attempt to delete non-existent moderator
  await TestValidator.error(
    "cannot delete already deleted moderator",
    async () => {
      await api.functional.discussionBoard.moderator.moderators.erase(
        connection,
        {
          username: targetUsername,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardModeratorSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModeratorSession";

/**
 * Test the ability for moderators to update session expiration times for proper
 * session lifecycle management. This scenario validates that session expiration
 * can be extended or shortened based on administrative needs while preserving
 * audit trail integrity for connection context fields. The test follows a
 * complete workflow: create a moderator account, establish an active session,
 * update the session expiration time, and verify the changes are properly
 * reflected while maintaining connection context integrity.
 */
export async function test_api_moderator_session_update_expiration_management(
  connection: api.IConnection,
) {
  // Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.alphabets(10);

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      username: moderatorUsername,
      password: "password123",
      moderation_level: "basic",
      href: "https://example.com/join",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Login to establish active session
  const loggedInModerator = await api.functional.auth.moderator.login(
    connection,
    {
      body: {
        email_or_username: moderatorEmail,
        password: "password123",
        href: "https://example.com/login",
        referrer: "https://example.com/join",
      } satisfies IDiscussionBoardModerator.ILogin,
    },
  );
  typia.assert(loggedInModerator);

  // Extend session expiration by 1 hour
  const extendedExpiration = new Date(Date.now() + 3600000).toISOString();

  const updatedSession =
    await api.functional.discussionBoard.moderator.moderators.sessions.update(
      connection,
      {
        username: moderatorUsername,
        sessionId: typia.assert(loggedInModerator.id!),
        body: {
          expired_at: extendedExpiration,
        } satisfies IDiscussionBoardModeratorSession.IUpdate,
      },
    );
  typia.assert(updatedSession);

  // Verify expiration was updated while preserving connection context
  TestValidator.equals(
    "session expiration should be extended",
    updatedSession.expired_at,
    extendedExpiration,
  );

  TestValidator.equals(
    "connection context should be preserved",
    updatedSession.href,
    "https://example.com/login",
  );

  TestValidator.equals(
    "moderator reference should be maintained",
    updatedSession.discussion_board_moderator_id,
    moderator.id,
  );

  // Shorten session expiration to test both directions
  const shortenedExpiration = new Date(Date.now() + 600000).toISOString(); // 10 minutes

  const sessionWithShortExpiration =
    await api.functional.discussionBoard.moderator.moderators.sessions.update(
      connection,
      {
        username: moderatorUsername,
        sessionId: updatedSession.id,
        body: {
          expired_at: shortenedExpiration,
        } satisfies IDiscussionBoardModeratorSession.IUpdate,
      },
    );
  typia.assert(sessionWithShortExpiration);

  // Verify the updated expiration time
  TestValidator.equals(
    "session expiration should be shortened",
    sessionWithShortExpiration.expired_at,
    shortenedExpiration,
  );

  // Verify all connection context fields remain unchanged
  TestValidator.equals(
    "IP address should remain unchanged",
    sessionWithShortExpiration.ip,
    updatedSession.ip,
  );

  TestValidator.equals(
    "referrer should remain unchanged",
    sessionWithShortExpiration.referrer,
    updatedSession.referrer,
  );

  TestValidator.equals(
    "moderator ID should remain unchanged",
    sessionWithShortExpiration.discussion_board_moderator_id,
    updatedSession.discussion_board_moderator_id,
  );
}

