/**
 * Test moderator access to post like analytics for content appreciation
 * metrics.
 *
 * This test validates that moderators can retrieve paginated like records for
 * discussion board posts with proper filtering and sorting capabilities. The
 * test focuses on testing the analytics API functionality without creating
 * actual posts since the post creation requires valid channel and section
 * references that don't exist in the test environment.
 */
export async function test_api_moderator_post_likes_analytics(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for authentication
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderator123";

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      username: RandomGenerator.alphabets(8),
      password: moderatorPassword,
      moderation_level: "senior",
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Test the like analytics API with a non-existent post ID
  // This tests the API's error handling and ensures the endpoint is accessible
  const nonExistentPostId = typia.random<string & tags.Format<"uuid">>();

  const emptyAnalytics =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: nonExistentPostId,
        body: {
          page: 1,
          limit: 10,
          order_by: "created_at",
          order: "desc",
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(emptyAnalytics);

  // Step 3: Validate pagination structure for empty results
  TestValidator.equals(
    "pagination structure exists",
    emptyAnalytics.pagination !== undefined,
    true,
  );
  TestValidator.equals(
    "current page is 1",
    emptyAnalytics.pagination.current,
    1,
  );
  TestValidator.equals("limit is 10", emptyAnalytics.pagination.limit, 10);
  TestValidator.equals(
    "records count is valid",
    emptyAnalytics.pagination.records >= 0,
    true,
  );
  TestValidator.equals(
    "pages count is valid",
    emptyAnalytics.pagination.pages >= 0,
    true,
  );

  // Step 4: Test filtering by date range with non-existent post
  const dateFilteredAnalytics =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: nonExistentPostId,
        body: {
          page: 1,
          limit: 10,
          date_from: new Date(Date.now() - 86400000).toISOString(), // 1 day ago
          date_to: new Date().toISOString(),
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(dateFilteredAnalytics);

  // Step 5: Test sorting by member with non-existent post
  const memberSortedAnalytics =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: nonExistentPostId,
        body: {
          page: 1,
          limit: 10,
          order_by: "member",
          order: "asc",
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(memberSortedAnalytics);

  // Step 6: Validate data structure for empty results
  TestValidator.predicate(
    "analytics API returns valid data structure",
    emptyAnalytics.data !== undefined && Array.isArray(emptyAnalytics.data),
  );
  TestValidator.equals(
    "empty result data array",
    emptyAnalytics.data.length,
    0,
  );

  // Step 7: Test different pagination parameters
  const secondPageAnalytics =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: nonExistentPostId,
        body: {
          page: 2,
          limit: 5,
          order_by: "created_at",
          order: "asc",
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(secondPageAnalytics);

  TestValidator.equals(
    "second page current page is 2",
    secondPageAnalytics.pagination.current,
    2,
  );
  TestValidator.equals(
    "second page limit is 5",
    secondPageAnalytics.pagination.limit,
    5,
  );

  // Step 8: Test maximum limit constraint
  const maxLimitAnalytics =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: nonExistentPostId,
        body: {
          page: 1,
          limit: 100, // Maximum allowed limit
          order_by: "created_at",
          order: "desc",
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(maxLimitAnalytics);

  TestValidator.equals(
    "maximum limit is respected",
    maxLimitAnalytics.pagination.limit,
    100,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostLike";

/**
 * Test advanced filtering capabilities for post like analytics.
 *
 * This E2E test validates the discussion board moderator post likes filtering
 * API by testing various filtering options including member-specific filtering,
 * date ranges, and sorting capabilities. The test focuses on validating the API
 * contract and filtering functionality assuming test data exists in the
 * system.
 *
 * Test workflow:
 *
 * 1. Create moderator account for authentication
 * 2. Test basic filtering with default parameters
 * 3. Test member-specific filtering
 * 4. Test date range filtering
 * 5. Test sorting options
 * 6. Test pagination behavior
 * 7. Test combined filtering with multiple criteria
 * 8. Validate empty filter results handling
 */
export async function test_api_moderator_post_likes_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        username: RandomGenerator.name(1),
        password: "moderator123",
        display_name: RandomGenerator.name(),
        bio: RandomGenerator.paragraph({ sentences: 5 }),
        moderation_level: "admin",
        href: "https://discussion-board.example.com",
        referrer: "https://discussion-board.example.com/register",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Use a valid post ID that should exist in the test environment
  const postId = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Test basic filtering with default parameters
  const basicFilterResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: postId,
        body: {
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(basicFilterResult);

  // Step 3: Test member-specific filtering
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const memberFilterResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: postId,
        body: {
          page: 1,
          limit: 10,
          member: {
            id: memberId,
            type: "member",
            name: RandomGenerator.name(),
          } satisfies IDiscussionBoardMember.ISummary,
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(memberFilterResult);

  // Step 4: Test date range filtering
  const currentDate = new Date().toISOString();
  const pastDate = new Date(Date.now() - 86400000).toISOString(); // 1 day ago

  const dateFilterResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: postId,
        body: {
          page: 1,
          limit: 10,
          date_from: pastDate,
          date_to: currentDate,
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(dateFilterResult);

  // Step 5: Test sorting by creation date
  const sortByDateResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: postId,
        body: {
          page: 1,
          limit: 10,
          order_by: "created_at",
          order: "desc",
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(sortByDateResult);

  // Step 6: Test sorting by member
  const sortByMemberResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: postId,
        body: {
          page: 1,
          limit: 10,
          order_by: "member",
          order: "asc",
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(sortByMemberResult);

  // Step 7: Test pagination with different page sizes
  const paginationTestResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: postId,
        body: {
          page: 1,
          limit: 5, // Smaller page size
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(paginationTestResult);

  // Step 8: Validate pagination metadata
  TestValidator.predicate(
    "pagination metadata should be valid",
    paginationTestResult.pagination.current >= 0 &&
      paginationTestResult.pagination.limit > 0 &&
      paginationTestResult.pagination.records >= 0 &&
      paginationTestResult.pagination.pages >= 0,
  );

  // Step 9: Test combined filtering with multiple criteria
  const combinedFilterResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: postId,
        body: {
          page: 1,
          limit: 10,
          member: {
            id: memberId,
            type: "member",
            name: RandomGenerator.name(),
          } satisfies IDiscussionBoardMember.ISummary,
          date_from: pastDate,
          date_to: currentDate,
          order_by: "created_at",
          order: "desc",
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(combinedFilterResult);

  // Step 10: Test edge case - empty filter results with future dates
  const futureDate = new Date(Date.now() + 86400000).toISOString(); // 1 day in future
  const emptyFilterResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: postId,
        body: {
          page: 1,
          limit: 10,
          date_from: futureDate, // No likes should exist in the future
          date_to: new Date(Date.now() + 172800000).toISOString(), // 2 days in future
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(emptyFilterResult);

  // Step 11: Validate empty result handling
  TestValidator.predicate(
    "empty filter result should have valid pagination",
    emptyFilterResult.pagination.records === 0 ||
      emptyFilterResult.pagination.records >= 0,
  );

  // Final validation: Ensure all API calls returned valid responses
  TestValidator.predicate(
    "all filtering operations completed successfully",
    basicFilterResult !== undefined &&
      memberFilterResult !== undefined &&
      dateFilterResult !== undefined &&
      sortByDateResult !== undefined &&
      sortByMemberResult !== undefined &&
      paginationTestResult !== undefined &&
      combinedFilterResult !== undefined &&
      emptyFilterResult !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostLike";

/**
 * Test pagination functionality for large like datasets
 *
 * Creates moderator account and test posts, then verifies pagination controls
 * work correctly with various page sizes and record counts. Ensures proper
 * calculation of total pages and record counts for accurate analytics
 * reporting.
 */
export async function test_api_moderator_post_likes_pagination(
  connection: api.IConnection,
) {
  // Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        username: RandomGenerator.name(1),
        password: "moderator123",
        moderation_level: "admin",
        href: "https://example.com/register",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Create multiple member accounts for context
  const members = await ArrayUtil.asyncRepeat(3, async (index) => {
    const memberEmail = typia.random<string & tags.Format<"email">>();
    const member: IDiscussionBoardMember.IAuthorized =
      await api.functional.auth.member.join(connection, {
        body: {
          email: memberEmail,
          username: RandomGenerator.name(1),
          password: "member123",
          href: "https://example.com/register",
          referrer: "https://example.com",
        } satisfies IDiscussionBoardMember.ICreate,
      });
    typia.assert(member);
    return member;
  });

  // Create multiple test posts
  const posts = await ArrayUtil.asyncRepeat(2, async (index) => {
    const post: IDiscussionBoardPost =
      await api.functional.discussionBoard.member.posts.create(connection, {
        body: {
          title: RandomGenerator.paragraph({
            sentences: 5,
            wordMin: 3,
            wordMax: 8,
          }),
          content: RandomGenerator.content({
            paragraphs: 2,
            sentenceMin: 10,
            sentenceMax: 15,
          }),
          discussion_board_channel_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          discussion_board_section_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        } satisfies IDiscussionBoardPost.ICreate,
      });
    typia.assert(post);
    return post;
  });

  // Switch back to moderator account for pagination testing
  await api.functional.auth.moderator.login(connection, {
    body: {
      email_or_username: moderatorEmail,
      password: "moderator123",
      href: "https://example.com/login",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Test pagination with different page sizes
  const testPageSizes = [5, 10, 20] as const;

  for (const pageSize of testPageSizes) {
    const paginationResult: IPageIDiscussionBoardPostLike.ISummary =
      await api.functional.discussionBoard.moderator.posts.likes.index(
        connection,
        {
          postId: posts[0].id,
          body: {
            page: 1,
            limit: pageSize,
            order_by: "created_at",
            order: "desc",
          } satisfies IDiscussionBoardPostLike.IRequest,
        },
      );
    typia.assert(paginationResult);

    // Validate pagination metadata
    TestValidator.equals(
      `page size ${pageSize} should return correct limit`,
      paginationResult.pagination.limit,
      pageSize,
    );
    TestValidator.predicate(
      `page size ${pageSize} should have valid record count`,
      paginationResult.pagination.records >= 0,
    );
    TestValidator.predicate(
      `page size ${pageSize} should have valid page count`,
      paginationResult.pagination.pages >= 0,
    );
    TestValidator.equals(
      `page size ${pageSize} should be on first page`,
      paginationResult.pagination.current,
      1,
    );

    // Validate data array size matches limit (or less if fewer records)
    TestValidator.predicate(
      `page size ${pageSize} data length should not exceed limit`,
      paginationResult.data.length <= pageSize,
    );
  }

  // Test different sorting options
  const sortingOptions = ["created_at", "member"] as const;

  for (const sortBy of sortingOptions) {
    const sortedResult: IPageIDiscussionBoardPostLike.ISummary =
      await api.functional.discussionBoard.moderator.posts.likes.index(
        connection,
        {
          postId: posts[0].id,
          body: {
            page: 1,
            limit: 10,
            order_by: sortBy,
            order: "asc",
          } satisfies IDiscussionBoardPostLike.IRequest,
        },
      );
    typia.assert(sortedResult);

    TestValidator.predicate(
      `sorting by ${sortBy} should return valid data`,
      Array.isArray(sortedResult.data),
    );
  }

  // Test date range filtering
  const dateFilteredResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: posts[0].id,
        body: {
          page: 1,
          limit: 10,
          date_from: new Date(
            Date.now() - 7 * 24 * 60 * 60 * 1000,
          ).toISOString(),
          date_to: new Date().toISOString(),
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(dateFilteredResult);

  TestValidator.predicate(
    "date filtered result should be valid",
    Array.isArray(dateFilteredResult.data),
  );

  // Validate pagination calculations with maximum page size
  const largePageResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: posts[0].id,
        body: {
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(largePageResult);

  // Verify pagination calculations are mathematically correct
  if (
    largePageResult.pagination.records > 0 &&
    largePageResult.pagination.limit > 0
  ) {
    const expectedPages = Math.ceil(
      largePageResult.pagination.records / largePageResult.pagination.limit,
    );
    TestValidator.equals(
      "pagination pages calculation should be correct",
      largePageResult.pagination.pages,
      expectedPages,
    );
  }

  // Test edge case: very small page size
  const smallPageResult: IPageIDiscussionBoardPostLike.ISummary =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: posts[0].id,
        body: {
          page: 1,
          limit: 1,
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(smallPageResult);

  TestValidator.equals(
    "smallest page size should have limit 1",
    smallPageResult.pagination.limit,
    1,
  );
  TestValidator.predicate(
    "smallest page size data length should be 0 or 1",
    smallPageResult.data.length <= 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostLike";

/**
 * Test comparative analytics between view and like metrics.
 *
 * Creates moderator account, creates posts with varying engagement patterns,
 * then analyzes both view and like data to identify content performance trends.
 * Validates that analytics provide insights into user engagement and content
 * appreciation patterns.
 */
export async function test_api_moderator_post_likes_comparison(
  connection: api.IConnection,
) {
  // Create moderator account for authentication context
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        username: RandomGenerator.alphabets(8),
        password: "password123",
        display_name: RandomGenerator.name(),
        bio: RandomGenerator.paragraph({ sentences: 3 }),
        moderation_level: "basic",
        href: "https://example.com",
        referrer: "https://example.com/referrer",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Create multiple member accounts for varied engagement
  const members: IDiscussionBoardMember.IAuthorized[] =
    await ArrayUtil.asyncRepeat(5, async (index) => {
      const memberEmail = typia.random<string & tags.Format<"email">>();
      const member: IDiscussionBoardMember.IAuthorized =
        await api.functional.auth.member.join(connection, {
          body: {
            email: memberEmail,
            username: RandomGenerator.alphabets(8),
            password: "password123",
            display_name: RandomGenerator.name(),
            bio: RandomGenerator.paragraph({ sentences: 2 }),
            href: "https://example.com",
            referrer: "https://example.com/referrer",
          } satisfies IDiscussionBoardMember.ICreate,
        });
      typia.assert(member);
      return member;
    });

  // Create test posts with varying content for comparative analysis
  const posts: IDiscussionBoardPost[] = [];

  // Create posts with different characteristics
  for (let i = 0; i < 3; i++) {
    // Switch to member context to create posts
    await api.functional.auth.member.login(connection, {
      body: {
        email: members[i].email,
        password: "password123",
        href: "https://example.com",
        referrer: "https://example.com/referrer",
      } satisfies IDiscussionBoardMember.ILogin,
    });

    const post = await api.functional.discussionBoard.member.posts.create(
      connection,
      {
        body: {
          title: RandomGenerator.paragraph({ sentences: 5 + i }), // Varying title length
          content: RandomGenerator.content({ paragraphs: 2 + i }), // Varying content length
          discussion_board_channel_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          discussion_board_section_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        } satisfies IDiscussionBoardPost.ICreate,
      },
    );
    typia.assert(post);
    posts.push(post);
  }

  // Simulate varying engagement patterns by having different members "like" different posts
  const engagementRecords: { postId: string; memberId: string }[] = [];

  // Post 0: High engagement (liked by all members)
  for (const member of members) {
    engagementRecords.push({ postId: posts[0].id, memberId: member.id });
  }

  // Post 1: Medium engagement (liked by first 3 members)
  for (let i = 0; i < 3; i++) {
    engagementRecords.push({ postId: posts[1].id, memberId: members[i].id });
  }

  // Post 2: Low engagement (liked by first member only)
  engagementRecords.push({ postId: posts[2].id, memberId: members[0].id });

  // Switch back to moderator context for analytics
  await api.functional.auth.moderator.login(connection, {
    body: {
      email_or_username: moderatorEmail,
      password: "password123",
      href: "https://example.com",
      referrer: "https://example.com/referrer",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Test comparative analytics on each post
  const analyticsResults: {
    post: IDiscussionBoardPost;
    analytics: IPageIDiscussionBoardPostLike.ISummary;
  }[] = [];

  for (const post of posts) {
    const analytics =
      await api.functional.discussionBoard.moderator.posts.likes.index(
        connection,
        {
          postId: post.id,
          body: {
            page: 1,
            limit: 20,
            order_by: "created_at",
            order: "desc",
          } satisfies IDiscussionBoardPostLike.IRequest,
        },
      );
    typia.assert(analytics);
    analyticsResults.push({ post, analytics });

    // Validate analytics structure
    TestValidator.equals(
      "pagination structure exists",
      typeof analytics.pagination,
      "object",
    );
    TestValidator.equals(
      "data array exists",
      Array.isArray(analytics.data),
      true,
    );
    TestValidator.predicate(
      "pagination has current page",
      analytics.pagination.current >= 0,
    );
    TestValidator.predicate(
      "pagination has limit",
      analytics.pagination.limit > 0,
    );
    TestValidator.predicate(
      "pagination has records count",
      analytics.pagination.records >= 0,
    );
    TestValidator.predicate(
      "pagination has pages count",
      analytics.pagination.pages >= 0,
    );

    // Validate each like record structure
    for (const likeRecord of analytics.data) {
      TestValidator.equals(
        "like record has id",
        typeof likeRecord.id,
        "string",
      );
      TestValidator.equals(
        "like record has member",
        typeof likeRecord.member,
        "object",
      );
      TestValidator.equals(
        "like record has post",
        typeof likeRecord.post,
        "object",
      );
      TestValidator.equals(
        "like record has created_at",
        typeof likeRecord.created_at,
        "string",
      );

      TestValidator.predicate("member has id", likeRecord.member.id.length > 0);
      TestValidator.predicate(
        "member has type",
        likeRecord.member.type.length > 0,
      );
      TestValidator.predicate(
        "member has name",
        likeRecord.member.name.length > 0,
      );

      TestValidator.predicate("post has id", likeRecord.post.id.length > 0);
      TestValidator.predicate("post has type", likeRecord.post.type.length > 0);
      TestValidator.predicate(
        "post has title",
        likeRecord.post.title.length > 0,
      );
    }
  }

  // Validate comparative analytics - posts should have different engagement levels
  // Note: Since we can't actually create likes through the API (no like creation endpoint),
  // we validate that the analytics structure is correct and can handle different scenarios
  TestValidator.equals(
    "analytics results count matches posts count",
    analyticsResults.length,
    posts.length,
  );

  // Validate that each post's analytics are properly associated
  for (const result of analyticsResults) {
    TestValidator.predicate(
      "analytics post association",
      result.analytics.data.every((like) => like.post.id === result.post.id),
    );
  }

  // Test filtering capabilities with date ranges
  const filteredAnalytics =
    await api.functional.discussionBoard.moderator.posts.likes.index(
      connection,
      {
        postId: posts[0].id,
        body: {
          page: 1,
          limit: 5,
          order_by: "member",
          order: "asc",
          date_from: new Date(Date.now() - 86400000).toISOString(), // Last 24 hours
          date_to: new Date().toISOString(),
        } satisfies IDiscussionBoardPostLike.IRequest,
      },
    );
  typia.assert(filteredAnalytics);

  TestValidator.equals(
    "filtered analytics has valid structure",
    typeof filteredAnalytics.pagination,
    "object",
  );
  TestValidator.equals(
    "filtered data is array",
    Array.isArray(filteredAnalytics.data),
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
