      email_or_username: moderatorEmail,
      password: "moderator123",
      ip: "192.168.1.1",
      href: "https://discussion-board.example.com/admin",
      referrer: "https://discussion-board.example.com/",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

