  await TestValidator.error("duplicate like should fail", async () => {
    await api.functional.discussionBoard.member.posts.likes.create(connection, {
      postId: post.id,
      body: {
        member_id: member.id,
      } satisfies IDiscussionBoardPostLike.ICreate,
    });
  });
