export async function patchDiscussionBoardSearchPosts(props: {
  body: IDiscussionBoardPost.IRequest;
}): Promise<IPageIDiscussionBoardPost.ISummary> {
  const {
    page,
    limit,
    search,
    discussion_board_channel_id,
    discussion_board_section_id,
    actor_type,
    status,
    is_pinned,
    is_locked,
    created_after,
    created_before,
    order_by,
    order_direction,
  } = props.body;

  const skip = (page - 1) * limit;

  // Build WHERE conditions with proper Prisma type
  const where: Prisma.discussion_board_postsWhereInput = {
    // Basic status filter (exclude deleted posts)
    status: { not: "deleted" },
  };

  // Text search on title and content
  if (search) {
    where.OR = [
      { title: { contains: search, mode: "insensitive" } },
      { content: { contains: search, mode: "insensitive" } },
    ];
  }

  // Channel filter
  if (discussion_board_channel_id) {
    where.discussion_board_channel_id = discussion_board_channel_id;
  }

  // Section filter
  if (discussion_board_section_id) {
    where.discussion_board_section_id = discussion_board_section_id;
  }

  // Actor type filter
  if (actor_type) {
    where.actor_type = actor_type;
  }

  // Status filter
  if (status) {
    where.status = status;
  }

  // Pin status filter
  if (is_pinned !== undefined) {
    where.is_pinned = is_pinned;
  }

  // Lock status filter
  if (is_locked !== undefined) {
    where.is_locked = is_locked;
  }

  // Date range filters - handle as ISO strings
  if (created_after || created_before) {
    where.created_at = {};
    if (created_after) {
      where.created_at.gte = created_after;
    }
    if (created_before) {
      where.created_at.lte = created_before;
    }
  }

  // Build ORDER BY
  const orderBy: Record<string, "asc" | "desc"> = {};
  const sortField = order_by || "created_at";
  const sortDirection = order_direction || "desc";

  if (sortField === "title") {
    orderBy.title = sortDirection;
  } else if (sortField === "published_at") {
    orderBy.published_at = sortDirection;
  } else if (sortField === "updated_at") {
    orderBy.updated_at = sortDirection;
  } else {
    orderBy.created_at = sortDirection;
  }

  // Handle pin priority sorting - remove redundant check
  orderBy.is_pinned = "desc";

  // Execute queries concurrently
  const [data, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_posts.findMany({
      where,
      skip,
      take: limit,
      orderBy,
      select: {
        id: true,
        title: true,
        actor_type: true,
        status: true,
        is_pinned: true,
        is_locked: true,
        created_at: true,
        updated_at: true,
        published_at: true,
        discussion_board_channel_id: true,
        discussion_board_section_id: true,
      },
    }),
    MyGlobal.prisma.discussion_board_posts.count({ where }),
  ]);

  // Convert to API response format
  const posts = data.map((post) => ({
    id: post.id as string & tags.Format<"uuid">,
    type: "post",
    title: post.title,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: posts,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthModeratorJoin(props: {
  body: IDiscussionBoardModerator.ICreate;
}): Promise<IDiscussionBoardModerator.IAuthorized> {
  // Check for existing moderator with same email or username
  const existingModerator =
    await MyGlobal.prisma.discussion_board_moderators.findFirst({
      where: {
        OR: [{ email: props.body.email }, { username: props.body.username }],
      },
    });

  if (existingModerator) {
    if (existingModerator.email === props.body.email) {
      throw new HttpException("Email already registered", 409);
    }
    if (existingModerator.username === props.body.username) {
      throw new HttpException("Username already taken", 409);
    }
  }

  // Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // Create moderator record
  const moderatorId = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  const moderator = await MyGlobal.prisma.discussion_board_moderators.create({
    data: {
      id: moderatorId,
      email: props.body.email,
      username: props.body.username,
      password_hash: hashedPassword,
      display_name: props.body.display_name ?? null,
      bio: props.body.bio ?? null,
      moderation_level: props.body.moderation_level,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // Create session record
  const sessionId = v4() as string & tags.Format<"uuid">;
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const session =
    await MyGlobal.prisma.discussion_board_moderator_sessions.create({
      data: {
        id: sessionId,
        discussion_board_moderator_id: moderatorId,
        ip: props.body.ip ?? "unknown",
        href: props.body.href,
        referrer: props.body.referrer,
        created_at: now,
        updated_at: now,
        expired_at: toISOStringSafe(accessExpires),
        deleted_at: null,
      },
    });

  // Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "moderator",
        id: moderatorId,
        session_id: sessionId,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "moderator",
        id: moderatorId,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Return authorized response
  return {
    id: moderatorId,
    email: moderator.email,
    username: moderator.username,
    display_name: moderator.display_name ?? undefined,
    bio: moderator.bio ?? undefined,
    moderation_level: moderator.moderation_level,
    created_at: toISOStringSafe(moderator.created_at),
    updated_at: toISOStringSafe(moderator.updated_at),
    deleted_at: moderator.deleted_at
      ? toISOStringSafe(moderator.deleted_at)
      : undefined,
    token,
  };
}

