  ]);

  // Transform results
  const data = queues.map((queue) => ({
    id: queue.id,
    queue_type: queue.queue_type,
    position: queue.position,
    discussion_board_content_report_id:
      queue.discussion_board_content_report_id,
    discussion_board_moderator_id:
      queue.discussion_board_moderator_id ?? undefined,
    assigned_at: queue.assigned_at
      ? toISOStringSafe(queue.assigned_at)
      : undefined,
    started_at: queue.started_at
      ? toISOStringSafe(queue.started_at)
      : undefined,
    completed_at: queue.completed_at
      ? toISOStringSafe(queue.completed_at)
      : undefined,
    timeout_at: toISOStringSafe(queue.timeout_at ?? new Date()),
    created_at: toISOStringSafe(queue.created_at),
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerationStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationStatistics";
import { IDiscussionBoardDateRange } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardDateRange";
import { IDiscussionBoardReportVolumeMetrics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportVolumeMetrics";
import { IDiscussionBoardEfficiencyMetrics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardEfficiencyMetrics";
import { IDiscussionBoardQueuePerformanceMetrics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardQueuePerformanceMetrics";
import { IDiscussionBoardModeratorWorkloadMetrics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModeratorWorkloadMetrics";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchDiscussionBoardModeratorModerationStatistics(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardModerationStatistics.IRequest;
}): Promise<IDiscussionBoardModerationStatistics> {
  // Parse date strings to Date objects for Prisma queries
  const startDate = new Date(props.body.dateRange.startDate + "T00:00:00.000Z");
  const endDate = new Date(props.body.dateRange.endDate + "T23:59:59.999Z");

  // Calculate time boundaries for different periods
  const now = new Date();
  const dailyStart = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const weeklyStart = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  const monthlyStart = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

  // Base where conditions for content reports
  const baseReportWhere: Record<string, unknown> = {
    created_at: {
      gte: startDate,
      lte: endDate,
    },
    deleted_at: null,
  };

  // Apply optional filters to base conditions
  if (
    props.body.priorityLevelFilter &&
    props.body.priorityLevelFilter !== "all"
  ) {
    baseReportWhere.priority = props.body.priorityLevelFilter;
  }

  if (props.body.reportTypeFilter && props.body.reportTypeFilter !== "all") {
    baseReportWhere.report_reason = props.body.reportTypeFilter;
  }

  // Base where conditions for moderation queues - use direct field references
  const baseQueueWhere: Record<string, unknown> = {
    discussion_board_content_report_id: {
      in: await MyGlobal.prisma.discussion_board_content_reports
        .findMany({
          where: {
            created_at: {
              gte: startDate,
              lte: endDate,
            },
            deleted_at: null,
          },
          select: { id: true },
        })
        .then((reports) => reports.map((r) => r.id)),
    },
    deleted_at: null,
  };

  // Apply queue type filter if specified
  if (props.body.queueTypeFilter && props.body.queueTypeFilter !== "all") {
    baseQueueWhere.queue_type = props.body.queueTypeFilter;
  }

  // Get report volume metrics
  const [
    dailyReports,
    weeklyReports,
    monthlyReports,
    pendingReports,
    totalReports,
  ] = await Promise.all([
    // Daily reports (last 24 hours)
    MyGlobal.prisma.discussion_board_content_reports.count({
      where: {
        ...baseReportWhere,
        created_at: {
          gte: dailyStart,
          lte: now,
        },
      },
    }),
    // Weekly reports (last 7 days)
    MyGlobal.prisma.discussion_board_content_reports.count({
      where: {
        ...baseReportWhere,
        created_at: {
          gte: weeklyStart,
          lte: now,
        },
      },
    }),
    // Monthly reports (last 30 days)
    MyGlobal.prisma.discussion_board_content_reports.count({
      where: {
        ...baseReportWhere,
        created_at: {
          gte: monthlyStart,
          lte: now,
        },
      },
    }),
    // Pending reports
    MyGlobal.prisma.discussion_board_content_reports.count({
      where: {
        ...baseReportWhere,
        status: "pending",
      },
    }),
    // Total reports in date range for percentage calculations
    MyGlobal.prisma.discussion_board_content_reports.count({
      where: baseReportWhere,
    }),
  ]);

  // Get efficiency metrics data
  const [assignedQueues, completedQueues, escalationActions] =
    await Promise.all([
      // Get queues with assignment times for response time calculation
      MyGlobal.prisma.discussion_board_moderation_queues.findMany({
        where: {
          ...baseQueueWhere,
          assigned_at: { not: null },
        },
        select: {
          assigned_at: true,
          discussion_board_content_report_id: true,
        },
      }),
      // Get completed queues for resolution time calculation
      MyGlobal.prisma.discussion_board_moderation_queues.findMany({
        where: {
          ...baseQueueWhere,
          assigned_at: { not: null },
          completed_at: { not: null },
        },
        select: {
          assigned_at: true,
          completed_at: true,
        },
      }),
      // Get escalation actions
      MyGlobal.prisma.discussion_board_moderation_actions.count({
        where: {
          escalation_level: { in: ["escalated", "critical"] },
          discussion_board_content_report_id: {
            in: await MyGlobal.prisma.discussion_board_content_reports
              .findMany({
                where: {
                  created_at: {
                    gte: startDate,
                    lte: endDate,
                  },
                  deleted_at: null,
                },
                select: { id: true },
              })
              .then((reports) => reports.map((r) => r.id)),
          },
          deleted_at: null,
        },
      }),
    ]);

  // Get report creation times for assigned queues
  const reportCreationTimes = await Promise.all(
    assignedQueues.map(async (queue) => {
      const report =
        await MyGlobal.prisma.discussion_board_content_reports.findUnique({
          where: { id: queue.discussion_board_content_report_id },
          select: { created_at: true },
        });
      return report?.created_at;
    }),
  );

  // Calculate efficiency metrics with proper null checks
  const responseTimes = assignedQueues
    .map((queue, index) => {
      const reportTime = reportCreationTimes[index]?.getTime();
      const assignTime = queue.assigned_at?.getTime();
      if (!reportTime || !assignTime) return null;
      return (assignTime - reportTime) / (1000 * 60 * 60); // Convert to hours
    })
    .filter((time): time is number => time !== null);

  const resolutionTimes = completedQueues
    .map((queue) => {
      const assignTime = queue.assigned_at?.getTime();
      const completeTime = queue.completed_at?.getTime();
      if (!assignTime || !completeTime) return null;
      return (completeTime - assignTime) / (1000 * 60 * 60); // Convert to hours
    })
    .filter((time): time is number => time !== null);

  const averageResponseTimeHours =
    responseTimes.length > 0
      ? responseTimes.reduce((sum, time) => sum + time, 0) /
        responseTimes.length
      : 0;

  const averageResolutionTimeHours =
    resolutionTimes.length > 0
      ? resolutionTimes.reduce((sum, time) => sum + time, 0) /
        resolutionTimes.length
      : 0;

  const resolutionRatePercentage =
    assignedQueues.length > 0
      ? (completedQueues.length / assignedQueues.length) * 100
      : 0;

  const escalationRatePercentage =
    totalReports > 0 ? (escalationActions / totalReports) * 100 : 0;

  // Get queue performance metrics
  const [generalQueues, urgentQueues, timeoutIncidents] = await Promise.all([
    // General queue wait times
    MyGlobal.prisma.discussion_board_moderation_queues.findMany({
      where: {
        ...baseQueueWhere,
        queue_type: "general",
        assigned_at: { not: null },
      },
      select: {
        assigned_at: true,
        discussion_board_content_report_id: true,
      },
    }),
    // Urgent queue wait times
    MyGlobal.prisma.discussion_board_moderation_queues.findMany({
      where: {
        ...baseQueueWhere,
        queue_type: "urgent",
        assigned_at: { not: null },
      },
      select: {
        assigned_at: true,
        discussion_board_content_report_id: true,
      },
    }),
    // Timeout incidents
    MyGlobal.prisma.discussion_board_moderation_queues.count({
      where: {
        ...baseQueueWhere,
        timeout_at: { not: null },
        completed_at: null,
      },
    }),
  ]);

  // Get report creation times for queue performance metrics
  const generalReportTimes = await Promise.all(
    generalQueues.map(async (queue) => {
      const report =
        await MyGlobal.prisma.discussion_board_content_reports.findUnique({
          where: { id: queue.discussion_board_content_report_id },
          select: { created_at: true },
        });
      return report?.created_at;
    }),
  );

  const urgentReportTimes = await Promise.all(
    urgentQueues.map(async (queue) => {
      const report =
        await MyGlobal.prisma.discussion_board_content_reports.findUnique({
          where: { id: queue.discussion_board_content_report_id },
          select: { created_at: true },
        });
      return report?.created_at;
    }),
  );

  // Calculate queue wait times with proper null checks
  const generalWaitTimes = generalQueues
    .map((queue, index) => {
      const reportTime = generalReportTimes[index]?.getTime();
      const assignTime = queue.assigned_at?.getTime();
      if (!reportTime || !assignTime) return null;
      return (assignTime - reportTime) / (1000 * 60 * 60); // Convert to hours
    })
    .filter((time): time is number => time !== null);

  const urgentWaitTimes = urgentQueues
    .map((queue, index) => {
      const reportTime = urgentReportTimes[index]?.getTime();
      const assignTime = queue.assigned_at?.getTime();
      if (!reportTime || !assignTime) return null;
      return (assignTime - reportTime) / (1000 * 60 * 60); // Convert to hours
    })
    .filter((time): time is number => time !== null);

  const generalQueueWaitTimeHours =
    generalWaitTimes.length > 0
      ? generalWaitTimes.reduce((sum, time) => sum + time, 0) /
        generalWaitTimes.length
      : 0;

  const urgentQueueWaitTimeHours =
    urgentWaitTimes.length > 0
      ? urgentWaitTimes.reduce((sum, time) => sum + time, 0) /
        urgentWaitTimes.length
      : 0;

  const assignmentCompletionRatePercentage =
    assignedQueues.length > 0
      ? (completedQueues.length / assignedQueues.length) * 100
      : 0;

  // Get moderator workload metrics
  const [activeModerators, moderatorAssignments] = await Promise.all([
    // Active moderators
    MyGlobal.prisma.discussion_board_moderators.count({
      where: {
        deleted_at: null,
      },
    }),
    // Moderator assignments for workload calculation
    MyGlobal.prisma.discussion_board_moderation_queues.groupBy({
      by: ["discussion_board_moderator_id"],
      _count: {
        id: true,
      },
      where: {
        ...baseQueueWhere,
        assigned_at: { not: null },
      },
    }),
  ]);

  // Calculate workload metrics
  const assignmentCounts = moderatorAssignments.map((group) => group._count.id);
  const averageReportsPerModerator =
    assignmentCounts.length > 0
      ? assignmentCounts.reduce((sum, count) => sum + count, 0) /
        assignmentCounts.length
      : 0;

  const meanWorkload =
    assignmentCounts.length > 0
      ? assignmentCounts.reduce((sum, count) => sum + count, 0) /
        assignmentCounts.length
      : 0;

  const workloadDistributionVariance =
    assignmentCounts.length > 0
      ? assignmentCounts.reduce(
          (sum, count) => sum + Math.pow(count - meanWorkload, 2),
          0,
        ) / assignmentCounts.length
      : 0;

  // Calculate trend direction
  const previousPeriodStart = new Date(
    startDate.getTime() - (endDate.getTime() - startDate.getTime()),
  );
  const previousPeriodEnd = new Date(startDate.getTime() - 1);

  const previousPeriodCount =
    await MyGlobal.prisma.discussion_board_content_reports.count({
      where: {
        created_at: {
          gte: previousPeriodStart,
          lte: previousPeriodEnd,
        },
        deleted_at: null,
      },
    });

  const trendDirection =
    totalReports > previousPeriodCount
      ? "increasing"
      : totalReports < previousPeriodCount
        ? "decreasing"
        : "stable";

  return {
    id: v4(),
    reportVolumeMetrics: {
      dailyReports,
      weeklyReports,
      monthlyReports,
      pendingReports,
      trendDirection,
    },
    efficiencyMetrics: {
      averageResponseTimeHours,
      averageResolutionTimeHours,
      resolutionRatePercentage,
      escalationRatePercentage,
    },
    queuePerformanceMetrics: {
      generalQueueWaitTimeHours,
      urgentQueueWaitTimeHours,
      assignmentCompletionRatePercentage,
      timeoutIncidentsCount: timeoutIncidents,
    },
    moderatorWorkloadMetrics: {
      activeModeratorsCount: activeModerators,
      averageReportsPerModerator,
      workloadDistributionVariance,
    },
    createdAt: toISOStringSafe(new Date()),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function postDiscussionBoardMemberPostsPostIdLikes(props: {
  member: MemberPayload;
  postId: string & tags.Format<"uuid">;
  body: IDiscussionBoardPostLike.ICreate;
}): Promise<IDiscussionBoardPostLike> {
  // Validate that the authenticated member matches the body member_id
  if (props.member.id !== props.body.member_id) {
    throw new HttpException("Member ID mismatch", 403);
  }

  // Verify the post exists and is accessible
  const post = await MyGlobal.prisma.discussion_board_posts.findUnique({
    where: { id: props.postId },
  });

  if (!post) {
    throw new HttpException("Post not found", 404);
  }

  // Check if post is published and accessible
  if (post.status !== "published" || post.deleted_at !== null) {
    throw new HttpException("Post is not accessible", 403);
  }

  // Check for existing like to prevent duplicates
  const existingLike =
    await MyGlobal.prisma.discussion_board_post_likes.findFirst({
      where: {
        discussion_board_member_id: props.body.member_id,
        discussion_board_post_id: props.postId,
        deleted_at: null,
      },
    });

  if (existingLike) {
    throw new HttpException("Post already liked by this member", 409);
  }

  // Verify the member exists
  const member = await MyGlobal.prisma.discussion_board_members.findUnique({
    where: { id: props.body.member_id },
  });

  if (!member || member.deleted_at !== null) {
    throw new HttpException("Member not found", 404);
  }

  const now = toISOStringSafe(new Date());

  // Create the like record
  const like = await MyGlobal.prisma.discussion_board_post_likes.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      discussion_board_member_id: props.body.member_id,
      discussion_board_post_id: props.postId,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
    include: {
      member: true,
      post: true,
    },
  });

  // Build member summary - use display_name or fallback to username or email
  const memberSummary: IDiscussionBoardMember.ISummary = {
    id: like.member.id,
    type: "member",
    name:
      like.member.display_name ||
      like.member.username ||
      like.member.email.split("@")[0],
  };

  // Build post summary
  const postSummary: IDiscussionBoardPost.ISummary = {
    id: like.post.id,
    type: "post",
    title: like.post.title,
  };

  return {
    id: like.id,
    member: memberSummary,
    post: postSummary,
    created_at: toISOStringSafe(like.created_at),
    updated_at: toISOStringSafe(like.updated_at),
    deleted_at: like.deleted_at ? toISOStringSafe(like.deleted_at) : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { IDiscussionBoardModeratorSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModeratorSession";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function postDiscussionBoardModeratorModerationActions(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardModerationAction.ICreate;
}): Promise<IDiscussionBoardModerationAction> {
  // Verify the moderator session exists
  const moderatorSession =
    await MyGlobal.prisma.discussion_board_moderator_sessions.findFirst({
      where: {
        id: props.moderator.session_id,
        deleted_at: null,
      },
    });

  if (!moderatorSession) {
    throw new HttpException("Moderator session not found", 404);
  }

  // Verify the content report exists and is not deleted
  const contentReport =
    await MyGlobal.prisma.discussion_board_content_reports.findFirst({
      where: {
        id: props.body.discussion_board_content_report_id,
        deleted_at: null,
      },
    });

  if (!contentReport) {
    throw new HttpException("Content report not found", 404);
  }

  // Verify the moderator exists and is not deleted
  const moderator = await MyGlobal.prisma.discussion_board_moderators.findFirst(
    {
      where: {
        id: props.moderator.id,
        deleted_at: null,
      },
    },
  );

  if (!moderator) {
    throw new HttpException("Moderator not found", 404);
  }

  const now = toISOStringSafe(new Date());

  try {
    // Create the moderation action without incorrect includes
    const created =
      await MyGlobal.prisma.discussion_board_moderation_actions.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          action_type: props.body.action_type,
          action_details: props.body.action_details ?? null,
          duration_days: props.body.duration_days ?? null,
          escalation_level: props.body.escalation_level,
          discussion_board_content_report_id:
            props.body.discussion_board_content_report_id,
          discussion_board_moderator_id: props.moderator.id,
          discussion_board_moderator_session_id: props.moderator.session_id,
          created_at: now,
          updated_at: now,
          deleted_at: null,
        },
      });

    // Transform the response according to DTO interfaces
    return {
      id: created.id,
      action_type: created.action_type,
      action_details:
        created.action_details === null ? undefined : created.action_details,
      duration_days:
        created.duration_days === null ? undefined : created.duration_days,
      escalation_level: created.escalation_level,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
      discussion_board_content_report_id:
        created.discussion_board_content_report_id,
      discussion_board_moderator_id: created.discussion_board_moderator_id,
      discussion_board_moderator_session_id:
        created.discussion_board_moderator_session_id,
    };
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      if (error.code === "P2003") {
        throw new HttpException("Foreign key constraint violation", 400);
      }
      if (error.code === "P2002") {
        throw new HttpException("Duplicate entry", 409);
      }
    }
    throw new HttpException("Internal server error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
