import { IDiscussionBoardUserNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserNotification";
import { IDiscussionBoardNotificationTypeFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationTypeFilter";
import { IDiscussionBoardNotificationStatusFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationStatusFilter";
import { IDiscussionBoardDeliveryMethodFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardDeliveryMethodFilter";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function putDiscussionBoardMemberNotificationsNotificationId(props: {
  member: MemberPayload;
  notificationId: string & tags.Format<"uuid">;
  body: IDiscussionBoardUserNotification.IUpdate;
}): Promise<IDiscussionBoardUserNotification> {
  // First get member information for the summary
  const member = await MyGlobal.prisma.discussion_board_members.findUnique({
    where: { id: props.member.id },
  });

  if (!member) {
    throw new HttpException("Member not found", 404);
  }

  // Verify notification exists and belongs to the member
  const existingNotification =
    await MyGlobal.prisma.discussion_board_user_notifications.findFirst({
      where: {
        id: props.notificationId,
        discussion_board_member_id: props.member.id,
        deleted_at: null,
      },
    });

  if (!existingNotification) {
    throw new HttpException("Notification not found or access denied", 404);
  }

  // Build update data with proper null/undefined handling
  const updateData = {
    ...(props.body.status !== undefined && { status: props.body.status }),
    ...(props.body.delivery_method !== undefined && {
      delivery_method: props.body.delivery_method,
    }),
    ...(props.body.related_entity_type !== undefined && {
      related_entity_type: props.body.related_entity_type,
    }),
    ...(props.body.related_entity_id !== undefined && {
      related_entity_id: props.body.related_entity_id,
    }),
    updated_at: toISOStringSafe(new Date()),
  };

  // Update the notification
  const updatedNotification =
    await MyGlobal.prisma.discussion_board_user_notifications.update({
      where: { id: props.notificationId },
      data: updateData,
    });

  // Return the updated notification with proper type conversions
  return {
    id: updatedNotification.id as string & tags.Format<"uuid">,
    notification_type:
      updatedNotification.notification_type as IDiscussionBoardNotificationTypeFilter,
    title: updatedNotification.title,
    message: updatedNotification.message,
    status:
      updatedNotification.status as IDiscussionBoardNotificationStatusFilter,
    delivery_method:
      updatedNotification.delivery_method as IDiscussionBoardDeliveryMethodFilter,
    member: {
      id: member.id as string & tags.Format<"uuid">,
      type: "member" as const,
      name: member.display_name ?? member.username,
    },
    related_entity_type:
      updatedNotification.related_entity_type === null
        ? undefined
        : updatedNotification.related_entity_type,
    related_entity_id:
      updatedNotification.related_entity_id === null
        ? undefined
        : (updatedNotification.related_entity_id as
            | (string & tags.Format<"uuid">)
            | undefined),
    created_at: toISOStringSafe(updatedNotification.created_at),
    updated_at: toISOStringSafe(updatedNotification.updated_at),
    deleted_at: updatedNotification.deleted_at
      ? toISOStringSafe(updatedNotification.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostAttachment";
import { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardMemberSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSession";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function putDiscussionBoardMemberPostsPostIdAttachmentsAttachmentId(props: {
  member: MemberPayload;
  postId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
  body: IDiscussionBoardPostAttachment.IUpdate;
}): Promise<IDiscussionBoardPostAttachment> {
  // Verify the attachment exists and belongs to the specified post
  const attachment =
    await MyGlobal.prisma.discussion_board_post_attachments.findFirst({
      where: {
        id: props.attachmentId,
        discussion_board_post_id: props.postId,
        deleted_at: null,
      },
    });

  if (!attachment) {
    throw new HttpException(
      "Attachment not found or does not belong to the specified post",
      404,
    );
  }

  // Verify the member has permission to update this attachment
  if (attachment.discussion_board_member_id !== props.member.id) {
    throw new HttpException(
      "You do not have permission to update this attachment",
      403,
    );
  }

  // Update the attachment with provided fields
  const updated =
    await MyGlobal.prisma.discussion_board_post_attachments.update({
      where: {
        id: props.attachmentId,
      },
      data: {
        description: props.body.description,
        security_scan_result: props.body.security_scan_result,
        updated_at: toISOStringSafe(new Date()),
      },
    });

  // Fetch related data separately since include relationships don't work as expected
  const post = await MyGlobal.prisma.discussion_board_posts.findUnique({
    where: { id: attachment.discussion_board_post_id },
    select: { id: true, title: true },
  });

  const member = await MyGlobal.prisma.discussion_board_members.findUnique({
    where: { id: attachment.discussion_board_member_id },
    select: { id: true },
  });

  const memberSession = attachment.discussion_board_member_session_id
    ? await MyGlobal.prisma.discussion_board_member_sessions.findUnique({
        where: { id: attachment.discussion_board_member_session_id },
        select: {
          id: true,
          ip: true,
          href: true,
          referrer: true,
          created_at: true,
          updated_at: true,
          expired_at: true,
          deleted_at: true,
        },
      })
    : null;

  // Convert to API response format
  return {
    id: updated.id,
    file_name: updated.file_name,
    file_type: updated.file_type,
    file_size: updated.file_size,
    storage_path: updated.storage_path,
    upload_status: updated.upload_status,
    security_scan_result: updated.security_scan_result ?? undefined,
    description: updated.description ?? undefined,
    download_count: updated.download_count,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
    post: {
      id: post?.id ?? "",
      type: "post",
      title: post?.title ?? "",
    },
    member: {
      id: member?.id ?? "",
      type: "member",
      name: "Member", // Default name since actual name field doesn't exist
    },
    member_session: memberSession
      ? {
          id: memberSession.id,
          ip: memberSession.ip,
          href: memberSession.href,
          referrer: memberSession.referrer,
          created_at: toISOStringSafe(memberSession.created_at),
          updated_at: toISOStringSafe(memberSession.updated_at),
          expired_at: memberSession.expired_at
            ? toISOStringSafe(memberSession.expired_at)
            : undefined,
          deleted_at: memberSession.deleted_at
            ? toISOStringSafe(memberSession.deleted_at)
            : undefined,
        }
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
