import { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { IDiscussionBoardModeratorSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModeratorSession";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function putDiscussionBoardModeratorModerationActionsActionId(props: {
  moderator: ModeratorPayload;
  actionId: string & tags.Format<"uuid">;
  body: IDiscussionBoardModerationAction.IUpdate;
}): Promise<IDiscussionBoardModerationAction> {
  // Verify the moderation action exists and belongs to the authenticated moderator
  const existingAction =
    await MyGlobal.prisma.discussion_board_moderation_actions.findFirst({
      where: {
        id: props.actionId,
        discussion_board_moderator_id: props.moderator.id,
        deleted_at: null,
      },
    });

  if (!existingAction) {
    throw new HttpException(
      "Moderation action not found or you don't have permission to update it",
      404,
    );
  }

  // Validate escalation_level if provided
  if (props.body.escalation_level !== undefined) {
    const validEscalationLevels = ["standard", "escalated", "critical"];
    if (!validEscalationLevels.includes(props.body.escalation_level)) {
      throw new HttpException(
        "Invalid escalation level. Must be one of: standard, escalated, critical",
        400,
      );
    }
  }

  // Prepare update data with only allowed fields
  const updateData: Prisma.discussion_board_moderation_actionsUpdateInput = {
    ...(props.body.action_details !== undefined && {
      action_details: props.body.action_details,
    }),
    ...(props.body.duration_days !== undefined && {
      duration_days: props.body.duration_days,
    }),
    ...(props.body.escalation_level !== undefined && {
      escalation_level: props.body.escalation_level,
    }),
    updated_at: toISOStringSafe(new Date()),
  };

  // Update the moderation action
  const updated =
    await MyGlobal.prisma.discussion_board_moderation_actions.update({
      where: { id: props.actionId },
      data: updateData,
    });

  return {
    id: updated.id as string & tags.Format<"uuid">,
    action_type: updated.action_type,
    action_details: updated.action_details ?? undefined,
    duration_days: updated.duration_days ?? undefined,
    escalation_level: updated.escalation_level,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    discussion_board_content_report_id:
      updated.discussion_board_content_report_id as string &
        tags.Format<"uuid">,
    discussion_board_moderator_id:
      updated.discussion_board_moderator_id as string & tags.Format<"uuid">,
    discussion_board_moderator_session_id:
      updated.discussion_board_moderator_session_id as string &
        tags.Format<"uuid">,
    contentReport: undefined,
    moderator: undefined,
    moderatorSession: undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerationQueues } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationQueues";
import { IDiscussionBoardContentReports } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReports";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import { IDiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerators";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function putDiscussionBoardModeratorModerationQueuesQueueId(props: {
  moderator: ModeratorPayload;
  queueId: string & tags.Format<"uuid">;
  body: IDiscussionBoardModerationQueues.IUpdate;
}): Promise<IDiscussionBoardModerationQueues> {
  // Verify the queue entry exists
  const existingQueue =
    await MyGlobal.prisma.discussion_board_moderation_queues.findUnique({
      where: { id: props.queueId },
    });

  if (!existingQueue) {
    throw new HttpException("Moderation queue entry not found", 404);
  }

  // Verify moderator has permission to modify this queue entry
  if (
    existingQueue.discussion_board_moderator_id &&
    existingQueue.discussion_board_moderator_id !== props.moderator.id
  ) {
    throw new HttpException(
      "You are not authorized to modify this queue entry",
      403,
    );
  }

  // Validate moderator_id if provided
  if (props.body.moderator_id !== undefined) {
    const moderatorExists =
      await MyGlobal.prisma.discussion_board_moderators.findUnique({
        where: { id: props.body.moderator_id },
      });
    if (!moderatorExists) {
      throw new HttpException("Specified moderator not found", 400);
    }
  }

  // Validate content_report_id if provided
  if (props.body.content_report_id !== undefined) {
    const contentReportExists =
      await MyGlobal.prisma.discussion_board_content_reports.findUnique({
        where: { id: props.body.content_report_id },
      });
    if (!contentReportExists) {
      throw new HttpException("Specified content report not found", 400);
    }
  }

  // Validate workflow state transitions
  if (
    props.body.completed_at &&
    !existingQueue.started_at &&
    !props.body.started_at
  ) {
    throw new HttpException(
      "Cannot mark as completed before starting review",
      400,
    );
  }

  if (props.body.started_at && existingQueue.completed_at) {
    throw new HttpException("Cannot restart a completed review", 400);
  }

  // Build update data with proper null/undefined handling
  const updateData: Prisma.discussion_board_moderation_queuesUpdateInput = {
    ...(props.body.queue_type !== undefined && {
      queue_type: props.body.queue_type,
    }),
    ...(props.body.position !== undefined && { position: props.body.position }),
    ...(props.body.assigned_at !== undefined && {
      assigned_at: props.body.assigned_at,
    }),
    ...(props.body.started_at !== undefined && {
      started_at: props.body.started_at,
    }),
    ...(props.body.completed_at !== undefined && {
      completed_at: props.body.completed_at,
    }),
    ...(props.body.timeout_at !== undefined && {
      timeout_at: props.body.timeout_at,
    }),
    ...(props.body.content_report_id !== undefined && {
      discussion_board_content_report_id: props.body.content_report_id,
    }),
    ...(props.body.moderator_id !== undefined && {
      discussion_board_moderator_id: props.body.moderator_id,
    }),
    updated_at: toISOStringSafe(new Date()),
  };

  // Perform the update
  const updated =
    await MyGlobal.prisma.discussion_board_moderation_queues.update({
      where: { id: props.queueId },
      data: updateData,
    });

  // Fetch related data separately
  const contentReport = updated.discussion_board_content_report_id
    ? await MyGlobal.prisma.discussion_board_content_reports.findUnique({
        where: { id: updated.discussion_board_content_report_id },
      })
    : null;

  const moderator = updated.discussion_board_moderator_id
    ? await MyGlobal.prisma.discussion_board_moderators.findUnique({
        where: { id: updated.discussion_board_moderator_id },
      })
    : null;

  // Transform to API response format
  return {
    id: updated.id,
    queue_type: updated.queue_type,
    position: updated.position,
    assigned_at: updated.assigned_at
      ? toISOStringSafe(updated.assigned_at)
      : undefined,
    started_at: updated.started_at
      ? toISOStringSafe(updated.started_at)
      : undefined,
    completed_at: updated.completed_at
      ? toISOStringSafe(updated.completed_at)
      : undefined,
    timeout_at: updated.timeout_at
      ? toISOStringSafe(updated.timeout_at)
      : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
    contentReport: contentReport
      ? {
          id: contentReport.id,
          report_type: contentReport.actor_type,
          status: contentReport.status,
          created_at: toISOStringSafe(contentReport.created_at),
          reporter: {
            id: contentReport.id,
            type: contentReport.actor_type,
            name: "Reporter",
          },
          content: {
            id: contentReport.id,
            type: contentReport.actor_type,
            title: `Report: ${contentReport.report_reason}`,
          },
        }
      : undefined,
    moderator: moderator
      ? {
          id: moderator.id,
          username: moderator.username,
          email: moderator.email,
          display_name: moderator.display_name || moderator.username,
          role: moderator.moderation_level,
          is_active: moderator.deleted_at === null,
        }
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function patchDiscussionBoardMemberPosts(props: {
  member: MemberPayload;
  body: IDiscussionBoardPost.IRequest;
}): Promise<IPageIDiscussionBoardPost.ISummary> {
  const page = props.body.page;
  const limit = props.body.limit;
  const skip = (page - 1) * limit;

  // Build WHERE conditions in a structured way
  const buildWhereConditions = () => {
    const conditions: Prisma.discussion_board_postsWhereInput = {
      deleted_at: null,
      status: { in: ["published", "archived"] },
    };

    // Search functionality - use OR for title/content search
    if (props.body.search) {
      conditions.OR = [
        { title: { contains: props.body.search, mode: "insensitive" } },
        { content: { contains: props.body.search, mode: "insensitive" } },
      ];
    }

    // Direct field filters
    if (props.body.discussion_board_channel_id) {
      conditions.discussion_board_channel_id =
        props.body.discussion_board_channel_id;
    }

    if (props.body.discussion_board_section_id) {
      conditions.discussion_board_section_id =
        props.body.discussion_board_section_id;
    }

    if (props.body.actor_type) {
      conditions.actor_type = props.body.actor_type;
    }

    if (props.body.status) {
      conditions.status = props.body.status;
    }

    if (props.body.is_pinned !== undefined) {
      conditions.is_pinned = props.body.is_pinned;
    }

    if (props.body.is_locked !== undefined) {
      conditions.is_locked = props.body.is_locked;
    }

    // Date range filtering
    if (props.body.created_after || props.body.created_before) {
      conditions.created_at = {};
      if (props.body.created_after) {
        conditions.created_at.gte = props.body.created_after;
      }
      if (props.body.created_before) {
        conditions.created_at.lte = props.body.created_before;
      }
    }

    return conditions;
  };

  const whereConditions = buildWhereConditions();

  // Determine sorting
  const determineOrderBy = () => {
    const orderDirection = props.body.order_direction ?? "desc";

    switch (props.body.order_by) {
      case "created_at":
        return { created_at: orderDirection };
      case "updated_at":
        return { updated_at: orderDirection };
      case "published_at":
        return { published_at: orderDirection };
      case "title":
        return { title: orderDirection };
      default:
        return { created_at: "desc" as Prisma.SortOrder };
    }
  };

  const orderBy = determineOrderBy();

  // Execute queries concurrently for better performance
  const [data, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_posts.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.discussion_board_posts.count({
      where: whereConditions,
    }),
  ]);

  // Transform data to match the API contract
  const transformedData: IDiscussionBoardPost.ISummary[] = data.map((post) => ({
    id: post.id as string & tags.Format<"uuid">,
    type: "post",
    title: post.title,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: transformedData,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";
import { IPageIDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentAttachment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function patchDiscussionBoardMemberCommentsCommentIdAttachments(props: {
  member: MemberPayload;
  commentId: string & tags.Format<"uuid">;
  body: IDiscussionBoardCommentAttachment.IRequest;
}): Promise<IPageIDiscussionBoardCommentAttachment.ISummary> {
  // Validate comment existence
  const comment = await MyGlobal.prisma.discussion_board_comments.findFirst({
    where: {
      id: props.commentId,
      deleted_at: null,
    },
  });

  if (!comment) {
    throw new HttpException("Comment not found", 404);
  }

  // Verify member has access to view this comment
  const canAccess = comment.discussion_board_member_id === props.member.id;
  if (!canAccess) {
    throw new HttpException("Access denied to this comment", 403);
  }

  // Pagination setup
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  // Build search conditions
  const whereCondition = {
    discussion_board_comment_id: props.commentId,
    deleted_at: null,
    ...(props.body.search && {
      OR: [
        { file_name: { contains: props.body.search } },
        { description: { contains: props.body.search } },
      ],
    }),
    ...(props.body.file_type && { file_type: props.body.file_type }),
    ...(props.body.upload_status && {
      upload_status: props.body.upload_status,
    }),
    ...(props.body.security_scan_result && {
      security_scan_result: props.body.security_scan_result,
    }),
    ...((props.body.created_at_start || props.body.created_at_end) && {
      created_at: {
        ...(props.body.created_at_start && {
          gte: props.body.created_at_start,
        }),
        ...(props.body.created_at_end && { lte: props.body.created_at_end }),
      },
    }),
  };

  // Sorting setup - fix orderBy to use proper Prisma SortOrder
  const orderBy = props.body.sort_by
    ? {
        ...(props.body.sort_by === "file_name" && {
          file_name:
            props.body.sort_order === "desc"
              ? Prisma.SortOrder.desc
              : Prisma.SortOrder.asc,
        }),
        ...(props.body.sort_by === "file_size" && {
          file_size:
            props.body.sort_order === "desc"
              ? Prisma.SortOrder.desc
              : Prisma.SortOrder.asc,
        }),
        ...(props.body.sort_by === "created_at" && {
          created_at:
            props.body.sort_order === "desc"
              ? Prisma.SortOrder.desc
              : Prisma.SortOrder.asc,
        }),
        ...(props.body.sort_by === "download_count" && {
          download_count:
            props.body.sort_order === "desc"
              ? Prisma.SortOrder.desc
              : Prisma.SortOrder.asc,
        }),
      }
    : { created_at: Prisma.SortOrder.desc };

  // Execute concurrent queries
  const [attachments, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_comment_attachments.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.discussion_board_comment_attachments.count({
      where: whereCondition,
    }),
  ]);

  // Transform to API response format
  const data = attachments.map((attachment) => ({
    id: attachment.id,
    file_name: attachment.file_name,
    file_type: attachment.file_type,
    file_size: attachment.file_size,
    storage_path: attachment.storage_path,
    upload_status: attachment.upload_status,
    security_scan_result: attachment.security_scan_result ?? "",
    description: attachment.description ?? undefined,
    download_count: attachment.download_count,
    created_at: toISOStringSafe(attachment.created_at),
    updated_at: toISOStringSafe(attachment.updated_at),
    deleted_at: attachment.deleted_at
      ? toISOStringSafe(attachment.deleted_at)
      : undefined,
  }));

  return {
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
