        where: {
          id: props.bookmarkId,
        },
        data: {
          deleted_at: new Date(),
          updated_at: new Date(),
        },
        include: {
          member: {
            select: {
              id: true,
              username: true,
            },
          },
          post: {
            select: {
              id: true,
